// Temporary local Editor probe only. No screenshots / debugger during timing.
using System;using System.IO;using System.Linq;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Profiling;using UnityEngine.Rendering;
using Unity.Profiling;using Unity.Profiling.LowLevel.Unsafe;using Newtonsoft.Json;
public static class CyberOrbPerformance {
 static string Out=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/CyberOrb/V3.2");
 class Phase{public int repeat,count;public string variant;public bool spread;}
 struct Row{public int phase,frame,batches,draws,setPass,particles;public double age,cpu,render,gpu,particle,gc;}
 static List<Phase> phases=new List<Phase>();static List<Row> rows=new List<Row>(24000);static List<GameObject> clones=new List<GameObject>();static ParticleSystem[] systems=new ParticleSystem[0];
 static Dictionary<string,ProfilerRecorder> counters=new Dictionary<string,ProfilerRecorder>();static int phase=-1,frame=-1;static double begin;static GameObject demo;static bool demoActive,background;static EditorWindow focused;static object environment;static List<object> memories=new List<object>();
 static double Read(string name,bool ms=true){ProfilerRecorder r;return counters.TryGetValue(name,out r)&&r.Valid&&r.Count>0?r.LastValue/(ms?1000000.0:1):double.NaN;}
 static object Stats(IEnumerable<double> values){var a=values.Where(v=>!double.IsNaN(v)&&!double.IsInfinity(v)).OrderBy(v=>v).ToArray();return a.Length==0?(object)new{available=false}:new{count=a.Length,median=a[a.Length/2],p95=a[(int)((a.Length-1)*.95)],max=a[a.Length-1]};}
 static void Next(){foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);clones.Clear();phase++;if(phase>=phases.Count){Finish();return;}var ph=phases[phase];for(int i=0;i<ph.count;i++){
   var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/CyberOrb/Prefabs/CyberOrb_"+(ph.variant=="Visual"?"ProjectileVisual":"Shot")+".prefab"));g.name="CyberOrb_Perf_"+i;g.transform.position=new Vector3(ph.variant=="Shot"?-3:0,ph.spread?i*.35f-.7f:1.8f,0);clones.Add(g);
   foreach(var p in g.GetComponentsInChildren<ParticleSystem>()){p.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);p.useAutoRandomSeed=false;p.randomSeed=(uint)(42+i*13);if(p.name=="BodyAndWake"||p.name=="CompactGlow"){var m=p.main;m.loop=true;}}
   foreach(var p in g.GetComponentsInChildren<ParticleSystem>().Where(p=>p.transform.parent==null||p.transform.parent.GetComponent<ParticleSystem>()==null))p.Play(true);
  }systems=clones.SelectMany(g=>g.GetComponentsInChildren<ParticleSystem>()).ToArray();begin=Time.timeAsDouble;
  File.WriteAllText(Path.Combine(Out,"PerformanceProgress.json"),JsonConvert.SerializeObject(new{phase,total=phases.Count,ph.count,ph.variant,ph.spread,ph.repeat}));memories.Add(new{phase,allocated=Profiler.GetTotalAllocatedMemoryLong(),reserved=Profiler.GetTotalReservedMemoryLong()});
 }
 static void Finish(string error=null){EditorApplication.update-=Tick;foreach(var g in clones)if(g!=null)UnityEngine.Object.Destroy(g);if(demo!=null)demo.SetActive(demoActive);Application.runInBackground=background;foreach(var r in counters.Values)r.Dispose();if(focused!=null)focused.Focus();
  File.WriteAllText(Path.Combine(Out,"PerformanceRaw.json"),JsonConvert.SerializeObject(new{environment,phases,rows,memories},Formatting.Indented));
  var groups=rows.GroupBy(r=>new{phases[r.phase].count,phases[r.phase].variant,phases[r.phase].spread}).Select(g=>new{instances=g.Key.count,g.Key.variant,g.Key.spread,frames=g.Count(),batches=Stats(g.Select(r=>(double)r.batches)),draws=Stats(g.Select(r=>(double)r.draws)),setPass=Stats(g.Select(r=>(double)r.setPass)),mainMs=Stats(g.Select(r=>r.cpu)),renderMs=Stats(g.Select(r=>r.render)),gpuMs=Stats(g.Select(r=>r.gpu)),particleMs=Stats(g.Select(r=>r.particle)),gcBytes=Stats(g.Select(r=>r.gc)),particles=Stats(g.Select(r=>(double)r.particles))}).ToArray();
  File.WriteAllText(Path.Combine(Out,"PerformanceSummary.json"),JsonConvert.SerializeObject(new{success=error==null,error,method="Real Play Mode, 0/1/8/32 Visual/Shot overlapping + 8 Visual distributed; two repetitions, 1.1s warmup + 3.3s sample/phase, every second engine frame. No captures/debugger. Whole-frame Editor counters include UI and probe; not standalone effect times. Unknown business budget: exploratory only.",environment,counters=counters.Keys,groups,memories,restored=true,pending=new[]{"Target Player/device / long-run pool memory","Per-pass GPU / overdraw","Exact batch merge / break reasons if FrameDebugger data unavailable"}},Formatting.Indented));
 }
 static void Tick(){try{if(!Application.isPlaying){Finish("Play Mode stopped");return;}if(frame==Time.frameCount||Time.frameCount%2!=0)return;frame=Time.frameCount;double age=Time.timeAsDouble-begin;if(age>=4.4){Next();return;}if(age<1.1)return;int count=0;for(int i=0;i<systems.Length;i++)count+=systems[i].particleCount;
  rows.Add(new Row{phase=phase,frame=frame,age=age,batches=UnityStats.batches,draws=UnityStats.drawCalls,setPass=UnityStats.setPassCalls,particles=count,cpu=Read("CPU Main Thread Frame Time"),render=Read("CPU Render Thread Frame Time"),gpu=Read("GPU Frame Time"),particle=Read("ParticleSystem.Update"),gc=Read("GC Allocated In Frame",false)});
 }catch(Exception e){Finish(e.ToString());}}
 public static string Run(){if(!Application.isPlaying||Application.dataPath!="/Users/user/Desktop/VFXDemo/VFXDemo/Assets"||SceneManager.GetActiveScene().path!="Assets/Scenes/VFXWorkbench.unity")throw new Exception("Wrong target/state");background=Application.runInBackground;Application.runInBackground=true;focused=EditorWindow.focusedWindow;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();demo=GameObject.Find("CyberOrb_Demo");demoActive=demo!=null&&demo.activeSelf;if(demo!=null)demo.SetActive(false);
  var available=new List<ProfilerRecorderHandle>();ProfilerRecorderHandle.GetAvailable(available);foreach(var name in new[]{"CPU Main Thread Frame Time","CPU Render Thread Frame Time","GPU Frame Time","ParticleSystem.Update","GC Allocated In Frame"}){var handle=available.FirstOrDefault(h=>ProfilerRecorderHandle.GetDescription(h).Name==name);if(handle.Valid){var d=ProfilerRecorderHandle.GetDescription(handle);counters[name]=ProfilerRecorder.StartNew(d.Category,name,1);}}
  var cam=Camera.main;environment=new{unity=Application.unityVersion,pipeline=GraphicsSettings.currentRenderPipeline.name,device=SystemInfo.graphicsDeviceName,api=SystemInfo.graphicsDeviceType.ToString(),editor=Application.isEditor,colorSpace=QualitySettings.activeColorSpace.ToString(),width=cam.pixelWidth,height=cam.pixelHeight,ortho=cam.orthographicSize,hdr=cam.allowHDR,msaa=cam.allowMSAA,vsync=QualitySettings.vSyncCount,target=Application.targetFrameRate,background=cam.backgroundColor.ToString(),allocatedMemory=Profiler.GetTotalAllocatedMemoryLong()};
  for(int repeat=0;repeat<2;repeat++){phases.Add(new Phase{repeat=repeat,count=0,variant="none"});foreach(var n in new[]{1,8,32})foreach(var v in new[]{"Visual","Shot"})phases.Add(new Phase{repeat=repeat,count=n,variant=v});phases.Add(new Phase{repeat=repeat,count=8,variant="Visual",spread=true});}Next();EditorApplication.update+=Tick;return "16 local baseline phases scheduled (~71s engine time); do not capture or use FrameDebugger until finished.";
 }
}
